package com.forgebingo.core;

/** Outcome of one HTTP call. {@code status == 0} means the request never completed. */
public final class ApiResult<T>
{
    public final int status;
    public final T body;
    /** Human-readable message. */
    public final String error;
    /** Machine code from the server's error body, e.g. invalid_rsn. */
    public final String errorCode;
    public final String etag;
    public final long retryAfterMillis;

    public ApiResult(int status, T body, String error, String errorCode, String etag, long retryAfterMillis)
    {
        this.status = status;
        this.body = body;
        this.error = error;
        this.errorCode = errorCode;
        this.etag = etag;
        this.retryAfterMillis = retryAfterMillis;
    }

    public ErrorClass errorClass()
    {
        return ErrorClass.of(status, errorCode);
    }

    public boolean ok()
    {
        return status >= 200 && status < 300;
    }

    public boolean notModified()
    {
        return status == 304;
    }

    /** True when this should leave a user-visible failure (not 304, not success). */
    public String describe()
    {
        if (status == 0)
        {
            return error == null ? "network error" : error;
        }
        String head = errorCode != null ? errorCode : error;
        return "HTTP " + status + (head == null ? "" : ": " + head) + (errorCode != null && error != null ? " (" + error + ")" : "");
    }
}

package com.forgebingo.core;

import java.util.Random;

/** Exponential backoff with jitter that honours Retry-After. */
public final class Backoff
{
    public static final long BASE_MILLIS = 5_000L;
    public static final long MAX_MILLIS = 15 * 60_000L;

    private Backoff()
    {
    }

    /**
     * @param attempt number of failed attempts so far (1 = first failure)
     * @param retryAfterMillis server hint, or &lt;= 0 for none
     * @param random jitter source (null for no jitter)
     */
    public static long delayMillis(int attempt, long retryAfterMillis, Random random)
    {
        int exponent = Math.min(Math.max(0, attempt - 1), 10);
        long delay = Math.min(MAX_MILLIS, BASE_MILLIS * (1L << exponent));
        if (random != null)
        {
            delay = (long) (delay * (0.8 + 0.4 * random.nextDouble()));
        }
        if (retryAfterMillis > 0)
        {
            delay = Math.max(delay, Math.min(retryAfterMillis, MAX_MILLIS));
        }
        return delay;
    }

    /** Parses a Retry-After header holding delta-seconds; HTTP-dates are ignored. */
    public static long parseRetryAfterMillis(String header)
    {
        if (header == null)
        {
            return 0;
        }
        try
        {
            long seconds = Long.parseLong(header.trim());
            return seconds <= 0 ? 0 : Math.min(seconds * 1000L, MAX_MILLIS);
        }
        catch (NumberFormatException ex)
        {
            return 0;
        }
    }
}

package com.forgebingo.core;

import java.awt.Rectangle;

/**
 * Where the on-screen board overlay goes (owner request, 2026-11-07): a centred board panel at most ~80% of the
 * smaller viewport side, its square grid of cells, the close button, the card a tile opens into, and hit-testing for
 * clicks. Pure and immutable, so the overlay (client thread) and the mouse listener (AWT thread) can share one.
 * Coordinates are game canvas coordinates: RuneLite's stretched mode translates mouse events into this space before
 * plugin listeners see them, and overlays draw in it too.
 */
public final class BoardLayout
{
    public static final double MAX_FRACTION = 0.8;
    public static final int MIN_CELL = 28;
    public static final int GAP = 4;
    public static final int PAD = 10;
    public static final int HEADER = 42;
    public static final int CLOSE = 20;
    /** space kept free around the board when a small viewport forces it bigger than MAX_FRACTION */
    public static final int MARGIN = 4;

    public final int viewW;
    public final int viewH;
    public final int size;
    public final int cell;
    public final int gap;
    private final int bx;
    private final int by;
    private final int bw;
    private final int bh;
    private final int gx;
    private final int gy;
    private final int cardX;
    private final int cardY;
    private final int cardW;
    private final int cardH;

    private BoardLayout(int viewW, int viewH, int size, int cell, int gap)
    {
        this.viewW = viewW;
        this.viewH = viewH;
        this.size = size;
        this.cell = cell;
        this.gap = gap;
        int grid = cell * size + gap * (size - 1);
        bw = grid + 2 * PAD;
        bh = grid + HEADER + 2 * PAD;
        bx = (viewW - bw) / 2;
        by = (viewH - bh) / 2;
        gx = bx + PAD;
        gy = by + HEADER + PAD;

        int maxW = Math.max(1, viewW - 16);
        int maxH = Math.max(1, viewH - 16);
        cardW = Math.min(maxW, Math.max(Math.min(260, maxW), (int) Math.round(bw * 0.6)));
        cardH = Math.min(maxH, Math.max(Math.min(220, maxH), (int) Math.round(bh * 0.7)));
        cardX = clamp(bx + (bw - cardW) / 2, 8, viewW - 8 - cardW);
        cardY = clamp(by + (bh - cardH) / 2, 8, viewH - 8 - cardH);
    }

    /** Lays out an N x N board (N clamped to 1..20) in a viewport of the given size. */
    public static BoardLayout compute(int viewW, int viewH, int boardSize)
    {
        int vw = Math.max(1, viewW);
        int vh = Math.max(1, viewH);
        int n = Math.max(1, Math.min(20, boardSize));
        int gap = GAP;
        int avail = (int) (Math.min(vw, vh) * MAX_FRACTION);
        // the panel is taller than wide (header), so the height decides the grid side
        int gridAvail = Math.min(avail - 2 * PAD, avail - HEADER - 2 * PAD);
        int cell = (gridAvail - gap * (n - 1)) / n;
        if (cell < MIN_CELL)
        {
            // small viewport or big board: grow towards MIN_CELL while the board still fits on screen
            int fit = Math.min(vw - 2 * MARGIN - 2 * PAD, vh - 2 * MARGIN - HEADER - 2 * PAD);
            int fitCell = (fit - gap * (n - 1)) / n;
            if (fitCell < 8)
            {
                gap = 1;
                fitCell = (fit - (n - 1)) / n;
            }
            cell = Math.max(cell, Math.min(MIN_CELL, fitCell));
        }
        return new BoardLayout(vw, vh, n, Math.max(2, cell), gap);
    }

    /** The whole board panel (background, header and grid). */
    public Rectangle board()
    {
        return new Rectangle(bx, by, bw, bh);
    }

    /** The square grid of cells inside the panel. */
    public Rectangle grid()
    {
        int side = cell * size + gap * (size - 1);
        return new Rectangle(gx, gy, side, side);
    }

    public Rectangle cell(int row, int col)
    {
        return new Rectangle(gx + col * (cell + gap), gy + row * (cell + gap), cell, cell);
    }

    /** The close button in the header's top-right corner. */
    public Rectangle closeButton()
    {
        return new Rectangle(bx + bw - PAD - CLOSE, by + PAD, CLOSE, CLOSE);
    }

    /** The card a clicked tile opens into: centred on the board, ~60% of its width, kept inside the viewport. */
    public Rectangle card()
    {
        return new Rectangle(cardX, cardY, cardW, cardH);
    }

    /** The small "no board yet" message box, centred. */
    public static Rectangle message(int viewW, int viewH)
    {
        int w = Math.min(Math.max(1, viewW - 16), 340);
        int h = Math.min(Math.max(1, viewH - 16), 64);
        return new Rectangle((viewW - w) / 2, (viewH - h) / 2, w, h);
    }

    /** Index (row * size + col) of the cell under the point, or -1 for the gaps and anything off the grid. */
    public int cellAt(int x, int y)
    {
        int dx = x - gx;
        int dy = y - gy;
        if (dx < 0 || dy < 0) return -1;
        int step = cell + gap;
        int col = dx / step;
        int row = dy / step;
        if (col >= size || row >= size) return -1;
        if (dx - col * step >= cell || dy - row * step >= cell) return -1;
        return row * size + col;
    }

    public boolean insideBoard(int x, int y)
    {
        return x >= bx && y >= by && x < bx + bw && y < by + bh;
    }

    public boolean onCloseButton(int x, int y)
    {
        return closeButton().contains(x, y);
    }

    public boolean insideCard(int x, int y)
    {
        return x >= cardX && y >= cardY && x < cardX + cardW && y < cardY + cardH;
    }

    /** Cubic ease-out over 0..1 (clamped): fast start, soft landing. */
    public static double easeOut(double t)
    {
        double c = Math.max(0, Math.min(1, t));
        return 1 - Math.pow(1 - c, 3);
    }

    private static int clamp(int v, int lo, int hi)
    {
        if (hi < lo) return Math.max(0, (lo + hi) / 2); // no room for the margins: centre it
        return Math.max(lo, Math.min(hi, v));
    }
}

package com.forgebingo.core;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Pure parsing of game chat messages. No RuneLite dependencies so it is unit-testable. */
public final class ChatParsers
{
    private static final Pattern TAGS = Pattern.compile("<[^>]*>");
    private static final Pattern COLLECTION_LOG = Pattern.compile("^New item added to your collection log: (.+?)\\.?$");
    // Counts above 999 are printed with thousands separators ("1,234").
    private static final Pattern KC = Pattern.compile(
        "^Your (?:completed |subdued )?(.+?) (?:(?:kill|harvest|lap|completion|chest) )?count is: ([0-9][0-9,]{0,12})\\.?$");
    private static final Pattern KC_FOR = Pattern.compile("^Your completion count for (.+?) is: ([0-9][0-9,]{0,12})\\.?$");
    /** "You have completed 12 hard Treasure Trails." (singular for the first one). */
    private static final Pattern CLUE = Pattern.compile(
        "^You have completed ([0-9][0-9,]{0,12}) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?$", Pattern.CASE_INSENSITIVE);
    private static final Pattern PET_NORMAL = Pattern.compile("^You have a funny feeling like you.?re being followed\\.?$");
    private static final Pattern PET_BACKPACK = Pattern.compile("^You feel something weird sneaking into your backpack\\.?$");
    private static final Pattern PET_DUPE = Pattern.compile("^You have a funny feeling like you would have been followed\\.{0,3}$");
    /**
     * Clan broadcast, the only line that names a duplicate pet:
     * "Zezima has a funny feeling like he's being followed: Vorki at 1,234 killcount.",
     * "Zezima feels something weird sneaking into her backpack: Heron at 99 Fishing.",
     * "Zezima has a funny feeling like they would have been followed: Olmlet at 50 killcount."
     */
    private static final Pattern PET_BROADCAST = Pattern.compile(
        "^([A-Za-z0-9 _-]{1,12}) (?:has a funny feeling like \\S+(?: \\S+)?? (?:(would have been)|(?:is |are )?being) followed"
            + "|feels something weird sneaking into \\S+ backpack): (.+?)(?: at [0-9][0-9,]* .*?)?\\.?$");

    private ChatParsers()
    {
    }

    public static String stripTags(String message)
    {
        if (message == null)
        {
            return "";
        }
        return TAGS.matcher(message).replaceAll("").replace(' ', ' ').trim();
    }

    public static final class Kc
    {
        public final String boss;
        public final int count;

        Kc(String boss, int count)
        {
            this.boss = boss;
            this.count = count;
        }
    }

    public static Optional<String> collectionLogItem(String message)
    {
        Matcher m = COLLECTION_LOG.matcher(stripTags(message));
        return m.matches() ? Optional.of(m.group(1).trim()) : Optional.empty();
    }

    public static Optional<Kc> killCount(String message)
    {
        String text = stripTags(message);
        Matcher m = KC.matcher(text);
        if (!m.matches())
        {
            m = KC_FOR.matcher(text);
            if (!m.matches())
            {
                return Optional.empty();
            }
        }
        Integer n = count(m.group(2));
        return n == null ? Optional.empty() : Optional.of(new Kc(m.group(1).trim(), n));
    }

    private static Integer count(String digits)
    {
        try
        {
            return Integer.parseInt(digits.replace(",", ""));
        }
        catch (NumberFormatException ex)
        {
            return null;
        }
    }

    public static final class Clue
    {
        /** lower-case tier: beginner .. master */
        public final String tier;
        public final int count;

        Clue(String tier, int count)
        {
            this.tier = tier;
            this.count = count;
        }

        /** sourceName for the {@code kc} event; an alias of the {@code clue_<tier>} catalogue source. */
        public String sourceName()
        {
            return "Clue scroll (" + tier + ")";
        }
    }

    /** Treasure Trail completion: "You have completed N <tier> Treasure Trails." */
    public static Optional<Clue> clueCompletion(String message)
    {
        Matcher m = CLUE.matcher(stripTags(message));
        if (!m.matches())
        {
            return Optional.empty();
        }
        Integer n = count(m.group(1));
        return n == null ? Optional.empty() : Optional.of(new Clue(m.group(2).toLowerCase(java.util.Locale.ROOT), n));
    }

    public enum Pet
    {
        /** New pet, now following the player. */
        FOLLOWING,
        /** New pet, put into the backpack (the player already had a follower). */
        BACKPACK,
        /** Duplicate: the player already owns it; nothing appears. */
        DUPLICATE;

        public boolean isNew()
        {
            return this != DUPLICATE;
        }
    }

    public static Optional<Pet> pet(String message)
    {
        String text = stripTags(message);
        if (PET_NORMAL.matcher(text).matches())
        {
            return Optional.of(Pet.FOLLOWING);
        }
        if (PET_BACKPACK.matcher(text).matches())
        {
            return Optional.of(Pet.BACKPACK);
        }
        if (PET_DUPE.matcher(text).matches())
        {
            return Optional.of(Pet.DUPLICATE);
        }
        return Optional.empty();
    }

    public static final class PetBroadcast
    {
        public final String player;
        public final String petName;
        public final boolean duplicate;

        PetBroadcast(String player, String petName, boolean duplicate)
        {
            this.player = player;
            this.petName = petName;
            this.duplicate = duplicate;
        }
    }

    /** A clan "funny feeling" broadcast; the caller checks {@code player} against the local player. */
    public static Optional<PetBroadcast> petBroadcast(String message)
    {
        Matcher m = PET_BROADCAST.matcher(stripTags(message));
        if (!m.matches())
        {
            return Optional.empty();
        }
        return Optional.of(new PetBroadcast(m.group(1).trim(), m.group(3).trim(), m.group(2) != null));
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.List;

/**
 * Turns server answers into the words the sidebar shows: connection state, the verified RSN, the event/team, and
 * what to do about a name mismatch or a revoked key. No RuneLite dependencies (unit-tested).
 */
public final class ConnectionStatus
{
    /** Where players get a key (website wording). */
    public static final String WHERE_TO_GET_A_KEY = "your team board on the ForgeBingo website > Connect RuneLite";

    public enum Level
    {
        OK,
        WARNING,
        ERROR
    }

    /** One line of the sidebar's status block. */
    public static final class Line
    {
        public final Level level;
        public final String text;

        public Line(Level level, String text)
        {
            this.level = level;
            this.text = text;
        }

        @Override
        public String toString()
        {
            return level + ": " + text;
        }
    }

    private ConnectionStatus()
    {
    }

    /** Message for a 401 (queue paused until the key changes). */
    public static String authMessage(String errorCode)
    {
        if ("api_key_revoked".equals(errorCode))
        {
            return "Your key was revoked or replaced by a newer one. Make a new key on " + WHERE_TO_GET_A_KEY
                + " and paste it in the ForgeBingo plugin settings.";
        }
        return "Key not recognised. Copy it again from " + WHERE_TO_GET_A_KEY + " and paste it in the ForgeBingo plugin settings.";
    }

    /** Lines for a hello response: one per event the key acts in. */
    public static List<Line> fromHello(ApiModels.HelloResponse r)
    {
        List<Line> out = new ArrayList<>();
        if (r == null || r.memberships == null || r.memberships.isEmpty())
        {
            out.add(new Line(Level.WARNING, "This key is not on any running bingo team. Join through your team link first."));
            return out;
        }
        for (ApiModels.Membership m : r.memberships)
        {
            out.add(line(m));
        }
        return out;
    }

    static Line line(ApiModels.Membership m)
    {
        String where = (m.eventName == null ? "the event" : m.eventName) + (m.teamName == null ? "" : " / " + m.teamName);
        String status = m.status == null ? "" : m.status;
        switch (status)
        {
            case "verified":
                return new Line(Level.OK, "Verified as " + m.pluginRsn + " - " + where);
            case "rsn_mismatch":
                return new Line(Level.ERROR, "RuneLite says you're logged in as " + m.pluginRsn + ", but you joined " + where
                    + " as " + m.joinedRsn + ". Fix your name on the team board (or log in on that account). Until then your drops wait for review.");
            case "account_mismatch":
                return new Line(Level.ERROR, where + " is linked to a different OSRS account. Log in on that account, or ask the organizer.");
            case "account_taken":
                return new Line(Level.ERROR, "This OSRS account is already linked to another player in " + where + ".");
            case "not_approved":
                return new Line(Level.WARNING, "Waiting for the organizer to approve you in " + where + ".");
            default:
                return new Line(Level.WARNING, where + ": " + status);
        }
    }

    /** True when every membership is verified (drops count automatically where the event auto-approves). */
    public static boolean allVerified(ApiModels.HelloResponse r)
    {
        if (r == null || r.memberships == null || r.memberships.isEmpty())
        {
            return false;
        }
        for (ApiModels.Membership m : r.memberships)
        {
            if (!m.verified)
            {
                return false;
            }
        }
        return true;
    }

    /** "Player key for X" / "Organizer key" line under the connection state. */
    public static String keyScope(ApiModels.Me me)
    {
        if (me == null)
        {
            return "";
        }
        return "event".equals(me.keyScope) ? "Player key (one event)" : "Account key (all your events)";
    }
}

package com.forgebingo.core;

/** How the queue should react to an HTTP outcome (docs/API.md section 8, "Limits and errors"). */
public enum ErrorClass
{
    /** 2xx. */
    SUCCESS,
    /** Network error, 408, 425, 429 (honour Retry-After), 5xx: retry with backoff. */
    TRANSIENT,
    /** 401 invalid_api_key: keep the events, pause sending, ask the user for a new key. */
    AUTH,
    /** 409 event_id_conflict: regenerate the eventId and retry. */
    CONFLICT,
    /**
     * 400 (invalid_payload, invalid_items, invalid_rsn, invalid_account_hash, unsupported_source_type,
     * occurred_at_out_of_range, invalid_json), 403 not_a_member (refresh the board list), 404, 413, 415 and
     * any other 4xx: the server will never accept this event. Drop it and tell the user.
     */
    PERMANENT;

    /** @param status HTTP status, or 0 for a network failure. */
    public static ErrorClass of(int status)
    {
        return of(status, null);
    }

    public static ErrorClass of(int status, String code)
    {
        if (status >= 200 && status < 300)
        {
            return SUCCESS;
        }
        if (status == 0 || status == 408 || status == 425 || status == 429 || status >= 500)
        {
            return TRANSIENT;
        }
        if (status == 401)
        {
            return AUTH;
        }
        if (status == 409 && "event_id_conflict".equals(code))
        {
            return CONFLICT;
        }
        return PERMANENT;
    }
}

package com.forgebingo.core;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Suppresses the same logical event seen twice in a short window (for example a
 * collection-log message emitted alongside a loot event, or a chat line replayed on login).
 */
public final class EventDeduplicator
{
    private final long windowMillis;
    private final int maxEntries;
    private final Map<String, Long> seen = new LinkedHashMap<>();

    public EventDeduplicator(long windowMillis, int maxEntries)
    {
        this.windowMillis = windowMillis;
        this.maxEntries = maxEntries;
    }

    public synchronized boolean firstSeen(String signature, long now)
    {
        seen.values().removeIf(t -> now - t > windowMillis);
        if (seen.containsKey(signature))
        {
            return false;
        }
        seen.put(signature, now);
        while (seen.size() > maxEntries)
        {
            seen.remove(seen.keySet().iterator().next());
        }
        return true;
    }

    public synchronized void clear()
    {
        seen.clear();
    }

    public static String signature(GameEvent e, int tick)
    {
        StringBuilder sb = new StringBuilder();
        sb.append(e.sourceType).append('|').append(e.sourceName).append('|').append(e.npcId)
            .append('|').append(e.skill).append('|').append(e.level).append('|').append(tick);
        if (e.items != null)
        {
            for (GameEvent.Item i : e.items)
            {
                sb.append('|').append(i.itemId).append('x').append(i.quantity);
            }
        }
        return sb.toString();
    }
}

package com.forgebingo.core;

import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.List;

/**
 * One thing that happened in game, as sent to {@code POST /v1/game-events} (docs/API.md section 8).
 * The server decides which team boards / tasks it counts for; the client never matches.
 *
 * <p>{@code id} is serialized as {@code eventId}: a UUID generated once and reused on every retry
 * (the server's idempotency key). {@code accountHash} is a decimal string (a 64-bit long would lose
 * precision in JSON).
 */
public final class GameEvent
{
    public static final String NPC = "npc";
    public static final String RAID_CHEST = "raid_chest";
    public static final String CLUE = "clue";
    public static final String COLLECTION_LOG = "collection_log";
    public static final String PET = "pet";
    public static final String KC = "kc";
    public static final String LEVEL = "level";

    public static final class Item
    {
        public int itemId;
        public int quantity;

        public Item()
        {
        }

        public Item(int itemId, int quantity)
        {
            this.itemId = itemId;
            this.quantity = quantity;
        }
    }

    @SerializedName("eventId")
    public String id;
    public String sourceType;
    /** ISO-8601; the server accepts now-1d .. now+5m. */
    public String occurredAt;
    /** Required, ^[A-Za-z0-9 _-]{1,12}$ */
    public String rsn;
    /** Required, client.getAccountHash() as a decimal string. */
    public String accountHash;
    /** npc */
    public Integer npcId;
    public String npcName;
    /** raid_chest / clue (tier) / kc (boss or raid name). */
    public String sourceName;
    /** Canonical (unnoted) item ids. Max 40. */
    public List<Item> items;
    /** level: lower-case skill name, or "overall". */
    public String skill;
    public Integer level;
    public String pluginVersion;
    public Integer world;

    public GameEvent()
    {
    }

    public GameEvent addItem(int itemId, int quantity)
    {
        if (items == null)
        {
            items = new ArrayList<>();
        }
        items.add(new Item(itemId, quantity));
        return this;
    }

    /** Human label for notices. */
    public String label()
    {
        if (sourceName != null && !sourceName.isEmpty())
        {
            return sourceName;
        }
        if (npcName != null && !npcName.isEmpty())
        {
            return npcName;
        }
        return skill != null ? skill : sourceType;
    }
}

package com.forgebingo.core;

import java.util.regex.Pattern;

/**
 * Guards icon loading: the plugin only loads item icons via ItemManager or the two server icon endpoints
 * ({@code /v1/icons/items/<id>.png}, {@code /v1/icons/tiles/<uuid>}). Never a URL taken from board data.
 */
public final class IconRef
{
    private static final Pattern PROXY = Pattern.compile(
        "^/v1/icons/(?:items/\\d{1,6}\\.png|tiles/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})$");

    private IconRef()
    {
    }

    public static boolean isProxyPath(String path)
    {
        return path != null && path.length() < 100 && PROXY.matcher(path).matches();
    }

    public static String item(int itemId)
    {
        return "/v1/icons/items/" + itemId + ".png";
    }
}

package com.forgebingo.core;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

/** Item-count snapshots of a container and what was added between two of them (pets put into the backpack). */
public final class InventoryDiff
{
    private InventoryDiff()
    {
    }

    /** item id -> total quantity; empty slots (id < 0 or quantity < 1) are ignored. */
    public static Map<Integer, Integer> counts(int[] ids, int[] quantities)
    {
        Map<Integer, Integer> m = new HashMap<>();
        if (ids == null)
        {
            return m;
        }
        for (int i = 0; i < ids.length; i++)
        {
            int q = quantities == null || i >= quantities.length ? 1 : quantities[i];
            if (ids[i] < 0 || q < 1)
            {
                continue;
            }
            m.merge(ids[i], q, Integer::sum);
        }
        return m;
    }

    /** Items whose count went up from {@code before} to {@code after}, with the increase (insertion order of {@code after}). */
    public static Map<Integer, Integer> added(Map<Integer, Integer> before, Map<Integer, Integer> after)
    {
        Map<Integer, Integer> out = new LinkedHashMap<>();
        if (after == null)
        {
            return out;
        }
        for (Map.Entry<Integer, Integer> e : after.entrySet())
        {
            int was = before == null ? 0 : before.getOrDefault(e.getKey(), 0);
            if (e.getValue() > was)
            {
                out.put(e.getKey(), e.getValue() - was);
            }
        }
        return out;
    }
}

package com.forgebingo.core;

import java.util.Collection;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;

/**
 * Item name -> canonical item id, for chat lines that only carry a name (the collection log). Built from the
 * server's item catalogue ({@code GET /v1/catalogue/items}), the item ids the current board's tasks ask for and
 * the static {@link PetTable}. Never relies on {@code ItemManager.search}, which only knows tradeable items.
 * Thread-safe: the index is replaced as a whole.
 */
public final class ItemNames
{
    private volatile Map<String, Integer> catalogue = new HashMap<>();
    private volatile Map<String, Integer> board = new HashMap<>();

    /** Lower-case, typographic apostrophes and non-breaking spaces folded, inner whitespace collapsed. */
    public static String normalize(String name)
    {
        if (name == null)
        {
            return "";
        }
        return name.replace('’', '\'').replace('‘', '\'').replace(' ', ' ')
            .trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /** Replace the catalogue part (id/name pairs from the server). For duplicate names the lowest id wins. */
    public void setCatalogue(Collection<ApiModels.CatalogueItem> items)
    {
        catalogue = index(items);
    }

    /** Replace the board part: names of the item ids the board's tasks ask for (from the item definitions). */
    public void setBoard(Collection<ApiModels.CatalogueItem> items)
    {
        board = index(items);
    }

    public int size()
    {
        return catalogue.size() + board.size();
    }

    private static Map<String, Integer> index(Collection<ApiModels.CatalogueItem> items)
    {
        Map<String, Integer> m = new HashMap<>();
        if (items == null)
        {
            return m;
        }
        for (ApiModels.CatalogueItem i : items)
        {
            if (i == null || i.name == null || i.id < 0)
            {
                continue;
            }
            String key = normalize(i.name);
            if (key.isEmpty())
            {
                continue;
            }
            m.merge(key, i.id, Math::min);
        }
        return m;
    }

    /** Pets first (static, always right), then the board's own items, then the server catalogue. */
    public Optional<Integer> resolve(String name)
    {
        String key = normalize(name);
        if (key.isEmpty())
        {
            return Optional.empty();
        }
        PetTable.Pet pet = PetTable.byName(key);
        if (pet != null)
        {
            return Optional.of(pet.primaryItemId());
        }
        Integer id = board.get(key);
        if (id == null)
        {
            id = catalogue.get(key);
        }
        return Optional.ofNullable(id);
    }
}

package com.forgebingo.core;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Durable FIFO of events not yet accepted by the server. Persisted as JSON in the plugin's own data folder through
 * RuneLite's Filepath API (atomic write via temp file + move) so a crash or client close loses nothing.
 * Bounded by count and age.
 */
public final class OfflineQueue
{
    private static final Logger log = LoggerFactory.getLogger(OfflineQueue.class);
    private static final Type LIST_TYPE = new TypeToken<List<QueuedEvent>>()
    {
    }.getType();

    public static final int MAX_ENTRIES = 500;
    /** The server rejects events older than one day, so there is no point keeping them longer. */
    public static final long MAX_AGE_MILLIS = 23 * 3_600_000L;

    private final Filepath file;
    private final Gson gson;
    private final Map<String, QueuedEvent> entries = new LinkedHashMap<>();

    public OfflineQueue(Filepath file, Gson gson)
    {
        this.file = file;
        this.gson = gson;
    }

    public synchronized void load()
    {
        entries.clear();
        if (!file.isFile())
        {
            return;
        }
        try (Reader reader = file.openBufferedReader())
        {
            List<QueuedEvent> loaded = gson.fromJson(reader, LIST_TYPE);
            if (loaded != null)
            {
                for (QueuedEvent q : loaded)
                {
                    if (q != null && q.event != null && q.event.id != null)
                    {
                        entries.put(q.event.id, q);
                    }
                }
            }
        }
        catch (IOException | RuntimeException ex)
        {
            // Corrupt file: keep a copy for inspection and start fresh.
            log.debug("Could not read queue file {}: {}", file, ex.toString());
            try
            {
                file.moveTo(file.getParent().joinSegment(file.getFileName() + ".corrupt"), StandardCopyOption.REPLACE_EXISTING);
            }
            catch (IOException | RuntimeException ignored)
            {
                // nothing more we can do
            }
        }
    }

    /** @return ids evicted because the queue was full (oldest first). */
    public synchronized List<QueuedEvent> add(QueuedEvent q)
    {
        entries.put(q.event.id, q);
        List<QueuedEvent> evicted = new ArrayList<>();
        Iterator<QueuedEvent> it = entries.values().iterator();
        while (entries.size() > MAX_ENTRIES && it.hasNext())
        {
            evicted.add(it.next());
            it.remove();
        }
        save();
        return evicted;
    }

    /** Removes and returns entries older than {@link #MAX_AGE_MILLIS}. */
    public synchronized List<QueuedEvent> expire(long now)
    {
        List<QueuedEvent> expired = new ArrayList<>();
        Iterator<QueuedEvent> it = entries.values().iterator();
        while (it.hasNext())
        {
            QueuedEvent q = it.next();
            if (now - q.createdAtMillis > MAX_AGE_MILLIS)
            {
                expired.add(q);
                it.remove();
            }
        }
        if (!expired.isEmpty())
        {
            save();
        }
        return expired;
    }

    public synchronized List<QueuedEvent> due(long now)
    {
        List<QueuedEvent> due = new ArrayList<>();
        for (QueuedEvent q : entries.values())
        {
            if (q.nextAttemptAtMillis <= now)
            {
                due.add(q);
            }
        }
        return due;
    }

    public synchronized void remove(String eventId)
    {
        if (entries.remove(eventId) != null)
        {
            save();
        }
    }

    public synchronized void scheduleRetry(String eventId, int attempts, long nextAttemptAt, String error)
    {
        QueuedEvent q = entries.get(eventId);
        if (q != null)
        {
            q.attempts = attempts;
            q.nextAttemptAtMillis = nextAttemptAt;
            q.lastError = error;
            save();
        }
    }

    /** Makes everything due now (used after the user fixes their key). */
    public synchronized void retryAllNow(long now)
    {
        for (QueuedEvent q : entries.values())
        {
            q.nextAttemptAtMillis = now;
        }
        save();
    }

    public synchronized int size()
    {
        return entries.size();
    }

    public synchronized void clear()
    {
        entries.clear();
        save();
    }

    private void save()
    {
        try
        {
            Filepath parent = file.getParent();
            parent.createDirectories();
            Filepath tmp = parent.joinSegment(file.getFileName() + ".tmp");
            try (Writer writer = tmp.openBufferedWriter())
            {
                gson.toJson(new ArrayList<>(entries.values()), LIST_TYPE, writer);
            }
            try
            {
                tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            }
            catch (AtomicMoveNotSupportedException ex)
            {
                tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        catch (IOException | RuntimeException ex)
        {
            log.debug("Could not persist queue to {}: {}", file, ex.toString());
        }
    }
}

package com.forgebingo.core;

import java.util.Collection;
import java.util.List;
import java.util.Optional;

/**
 * Works out WHICH pet a "funny feeling" chat line was about. The line itself names no pet, so it is paired, within
 * {@link #WINDOW_TICKS} game ticks either way, with the first of:
 * <ol>
 *   <li>the collection log line "New item added to your collection log: &lt;pet&gt;" (when that game setting is on);</li>
 *   <li>the clan broadcast "&lt;you&gt; has a funny feeling like ... followed: &lt;pet&gt;" (the only signal for duplicates);</li>
 *   <li>a new follower NPC (the "being followed" case), mapped NPC id -> pet;</li>
 *   <li>a pet item that appeared in the inventory (the "sneaking into your backpack" case);</li>
 *   <li>when the window closes unresolved: the boss / activity the player just killed or looted, if it has exactly one pet.</li>
 * </ol>
 * Pure state machine (no RuneLite types) driven by the plugin on the client thread. Each method returns the
 * pet drop to report, at most once per chat line.
 */
public final class PetDetector
{
    public static final int WINDOW_TICKS = 10;

    /** A pet to report. {@code pet} is null when the pet could not be identified. */
    public static final class Drop
    {
        public final PetTable.Pet pet;
        public final boolean duplicate;
        /** collection_log | broadcast | follower | inventory | source | unidentified */
        public final String via;

        Drop(PetTable.Pet pet, boolean duplicate, String via)
        {
            this.pet = pet;
            this.duplicate = duplicate;
            this.via = via;
        }

        public boolean identified()
        {
            return pet != null;
        }
    }

    private ChatParsers.Pet pending;
    private int pendingTick;
    /** A pet named (collection log / broadcast) before the chat line arrived. */
    private PetTable.Pet early;
    private boolean earlyDuplicate;
    private String earlyVia;
    private int earlyTick = Integer.MIN_VALUE / 2;
    /** Last boss / activity seen (loot, kill count, clue). */
    private String source;
    private int sourceTick = Integer.MIN_VALUE / 2;
    /** Tick of the last resolution, so a late second signal for the same pet is not paired with nothing. */
    private int resolvedTick = Integer.MIN_VALUE / 2;

    public boolean pending()
    {
        return pending != null;
    }

    /** The follower / inventory checks only matter while a line waits for its pet. */
    public boolean wantsFollower()
    {
        return pending == ChatParsers.Pet.FOLLOWING;
    }

    public boolean wantsInventory()
    {
        return pending == ChatParsers.Pet.BACKPACK;
    }

    public void reset()
    {
        pending = null;
        early = null;
        source = null;
        sourceTick = earlyTick = resolvedTick = Integer.MIN_VALUE / 2;
    }

    /** A "funny feeling" / "sneaking into your backpack" line. */
    public Optional<Drop> onPetMessage(ChatParsers.Pet kind, int tick)
    {
        pending = kind;
        pendingTick = tick;
        if (early != null && tick - earlyTick <= WINDOW_TICKS)
        {
            boolean dup = kind == ChatParsers.Pet.DUPLICATE || earlyDuplicate;
            return resolve(early, dup, earlyVia, tick);
        }
        return Optional.empty();
    }

    /** Any collection log line: only pet names matter here. */
    public Optional<Drop> onCollectionLog(String itemName, int tick)
    {
        return named(PetTable.byName(itemName), false, "collection_log", tick);
    }

    /** A clan pet broadcast already checked to be about the local player. */
    public Optional<Drop> onBroadcast(String petName, boolean duplicate, int tick)
    {
        return named(PetTable.byName(petName), duplicate, "broadcast", tick);
    }

    private Optional<Drop> named(PetTable.Pet pet, boolean duplicate, String via, int tick)
    {
        if (pet == null)
        {
            return Optional.empty();
        }
        if (pending != null)
        {
            return resolve(pet, pending == ChatParsers.Pet.DUPLICATE || duplicate, via, tick);
        }
        if (tick - resolvedTick <= WINDOW_TICKS)
        {
            return Optional.empty(); // second signal for a pet already reported
        }
        early = pet;
        earlyDuplicate = duplicate;
        earlyVia = via;
        earlyTick = tick;
        return Optional.empty();
    }

    /** The local player's follower NPC id (polled each tick while {@link #wantsFollower()}). */
    public Optional<Drop> onFollower(int npcId, int tick)
    {
        if (pending != ChatParsers.Pet.FOLLOWING)
        {
            return Optional.empty();
        }
        PetTable.Pet pet = PetTable.byFollowerNpcId(npcId);
        return pet == null ? Optional.empty() : resolve(pet, false, "follower", tick);
    }

    /** Item ids just added to the inventory (see {@link InventoryDiff#added}). */
    public Optional<Drop> onInventoryAdded(Collection<Integer> itemIds, int tick)
    {
        if (pending != ChatParsers.Pet.BACKPACK || itemIds == null)
        {
            return Optional.empty();
        }
        for (Integer id : itemIds)
        {
            PetTable.Pet pet = id == null ? null : PetTable.byItemId(id);
            if (pet != null)
            {
                return resolve(pet, false, "inventory", tick);
            }
        }
        return Optional.empty();
    }

    /** The boss / activity of a loot, kill count or clue event (for duplicates that nothing else names). */
    public void onSource(String name, int tick)
    {
        if (name != null && !name.isEmpty())
        {
            source = name;
            sourceTick = tick;
        }
    }

    /** Once per game tick: gives up on a line after the window, attributing it to the last source if unambiguous. */
    public Optional<Drop> onTick(int tick)
    {
        if (early != null && tick - earlyTick > WINDOW_TICKS)
        {
            early = null;
        }
        if (pending == null || tick - pendingTick <= WINDOW_TICKS)
        {
            return Optional.empty();
        }
        boolean dup = pending == ChatParsers.Pet.DUPLICATE;
        if (source != null && Math.abs(sourceTick - pendingTick) <= WINDOW_TICKS)
        {
            List<PetTable.Pet> pets = PetTable.bySource(source);
            if (pets.size() == 1)
            {
                return resolve(pets.get(0), dup, "source", tick);
            }
        }
        pending = null;
        resolvedTick = tick;
        return Optional.of(new Drop(null, dup, "unidentified"));
    }

    private Optional<Drop> resolve(PetTable.Pet pet, boolean duplicate, String via, int tick)
    {
        pending = null;
        early = null;
        resolvedTick = tick;
        return Optional.of(new Drop(pet, duplicate, via));
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Static table of every pet: in-game item name, item ids (base form first, then metamorph variants) and the follower
 * NPC ids that walk behind the player. Pets are untradeable, so {@code ItemManager.search} (tradeables only) can
 * never resolve them; this table is the plugin's only source for pet ids.
 *
 * <p>Ids come from the RuneLite gameval tables ({@code ItemID} / {@code NpcID}, follower NPCs only: the house
 * menagerie copies are left out). {@code sources} are lower-case boss / activity names as the plugin sees them in
 * loot, kill count and clue events; they are only used to attribute a duplicate pet, which names no pet at all.
 */
public final class PetTable
{
    public static final class Pet
    {
        public final String name;
        /** Base item first. Every id is sent, so a task listing any variant matches. */
        public final int[] itemIds;
        public final int[] followerNpcIds;
        public final List<String> sources;

        Pet(String name, int[] itemIds, int[] followerNpcIds, List<String> sources)
        {
            this.name = name;
            this.itemIds = itemIds;
            this.followerNpcIds = followerNpcIds;
            this.sources = sources;
        }

        public int primaryItemId()
        {
            return itemIds[0];
        }

        @Override
        public String toString()
        {
            return name;
        }
    }

    private static final List<Pet> PETS = Collections.unmodifiableList(build());
    private static final Map<String, Pet> BY_NAME = new HashMap<>();
    private static final Map<Integer, Pet> BY_ITEM = new HashMap<>();
    private static final Map<Integer, Pet> BY_NPC = new HashMap<>();
    private static final Map<String, List<Pet>> BY_SOURCE = new HashMap<>();

    static
    {
        for (Pet p : PETS)
        {
            put(BY_NAME, ItemNames.normalize(p.name), p);
            for (int id : p.itemIds) put(BY_ITEM, id, p);
            for (int id : p.followerNpcIds) put(BY_NPC, id, p);
            for (String s : p.sources) BY_SOURCE.computeIfAbsent(ItemNames.normalize(s), k -> new ArrayList<>()).add(p);
        }
    }

    private PetTable()
    {
    }

    private static <K> void put(Map<K, Pet> map, K key, Pet p)
    {
        Pet old = map.put(key, p);
        if (old != null && old != p)
        {
            throw new IllegalStateException("pet table: " + key + " used by " + old + " and " + p);
        }
    }

    public static List<Pet> all()
    {
        return PETS;
    }

    /** By in-game item name (case, apostrophe and whitespace insensitive). */
    public static Pet byName(String name)
    {
        return name == null ? null : BY_NAME.get(ItemNames.normalize(name));
    }

    public static Pet byItemId(int itemId)
    {
        return BY_ITEM.get(itemId);
    }

    public static Pet byFollowerNpcId(int npcId)
    {
        return BY_NPC.get(npcId);
    }

